// semver-range.js
//
// Precedence and range checking for MAJOR.MINOR.PATCH versions with optional
// -PRERELEASE and +BUILD suffixes. Pure string logic: no clock, network, or
// filesystem access at import time. Invalid versions or ranges throw Error.
//
// CLI: node semver-range.js INPUT_JSON_FILE
//   The input file must contain a non-null, non-array JSON object with
//   "versions" (a dense array of version strings) and "range" (a range
//   string). On success prints one JSON value {sorted, satisfying} followed
//   by a newline and exits 0; invalid arguments, files, JSON, or API input
//   exits 2 with a message on stderr and nothing on stdout.

import {readFileSync, realpathSync} from 'node:fs';
import {pathToFileURL} from 'node:url';

const VERSION_PATTERN = new RegExp(
  '^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)' +
    '(?:-([0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*))?' +
    '(?:\\+([0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*))?$'
);
const NUMERIC_IDENTIFIER = /^[0-9]+$/;
const LEADING_ZERO = /^0[0-9]/;
const OPERATORS = ['>=', '<=', '>', '<', '='];

// Parse a version string into {raw, major, minor, patch (BigInt),
// prerelease (string[]), hasPrerelease}. Throws Error on invalid input.
function parseVersion(value) {
  if (typeof value !== 'string') {
    throw new Error('invalid version: expected a string');
  }
  const match = VERSION_PATTERN.exec(value);
  if (!match) throw new Error(`invalid version: ${value}`);
  const prerelease = match[4] === undefined ? [] : match[4].split('.');
  for (const identifier of prerelease) {
    if (NUMERIC_IDENTIFIER.test(identifier) && LEADING_ZERO.test(identifier)) {
      throw new Error(
        `invalid version (numeric prerelease identifier with leading zero): ${value}`
      );
    }
  }
  return {
    raw: value,
    major: BigInt(match[1]),
    minor: BigInt(match[2]),
    patch: BigInt(match[3]),
    prerelease,
    hasPrerelease: prerelease.length > 0,
  };
}

// Compare two prerelease identifiers: numeric identifiers compare numerically,
// non-numeric identifiers compare by ASCII order, numeric is always below
// non-numeric. Returns -1, 0 or 1.
function compareIdentifiers(left, right) {
  const leftNumeric = NUMERIC_IDENTIFIER.test(left);
  const rightNumeric = NUMERIC_IDENTIFIER.test(right);
  if (leftNumeric && rightNumeric) {
    const a = BigInt(left);
    const b = BigInt(right);
    return a < b ? -1 : a > b ? 1 : 0;
  }
  if (leftNumeric) return -1;
  if (rightNumeric) return 1;
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

// Compare two parsed versions by precedence. Build metadata is ignored.
// Returns -1, 0 or 1.
function compareVersionsParsed(x, y) {
  for (const key of ['major', 'minor', 'patch']) {
    if (x[key] < y[key]) return -1;
    if (x[key] > y[key]) return 1;
  }
  // A version with a prerelease has lower precedence than the same version
  // without one.
  if (x.hasPrerelease !== y.hasPrerelease) return x.hasPrerelease ? -1 : 1;
  const left = x.prerelease;
  const right = y.prerelease;
  const shared = Math.min(left.length, right.length);
  for (let i = 0; i < shared; i += 1) {
    const order = compareIdentifiers(left[i], right[i]);
    if (order !== 0) return order;
  }
  // All shared identifiers equal: the shorter list is lower.
  if (left.length !== right.length) return left.length < right.length ? -1 : 1;
  return 0;
}

export function compareVersions(a, b) {
  return compareVersionsParsed(parseVersion(a), parseVersion(b));
}

// Parse one comparator token: an optional operator followed by a version.
function parseComparator(token) {
  let operator = '=';
  let versionText = token;
  for (const candidate of OPERATORS) {
    if (token.startsWith(candidate)) {
      operator = candidate;
      versionText = token.slice(candidate.length);
      break;
    }
  }
  return {operator, parsed: parseVersion(versionText)};
}

// Parse a range into an array of clauses; each clause is an array of
// comparators. Throws Error on invalid ranges (including empty clauses).
function parseRange(range) {
  if (typeof range !== 'string') {
    throw new Error('invalid range: expected a string');
  }
  return range.split('||').map((clause) => {
    const tokens = clause.trim().split(/\s+/).filter((token) => token.length > 0);
    if (tokens.length === 0) throw new Error('invalid range: empty clause');
    return tokens.map(parseComparator);
  });
}

function operatorHolds(operator, order) {
  switch (operator) {
    case '=': return order === 0;
    case '<': return order < 0;
    case '<=': return order <= 0;
    case '>': return order > 0;
    case '>=': return order >= 0;
    default: return false;
  }
}

// True when every comparator in the clause holds and, for a prerelease
// version, the clause contains a prerelease comparator with the same major,
// minor and patch.
function clauseSatisfies(parsed, comparators) {
  for (const {operator, parsed: target} of comparators) {
    if (!operatorHolds(operator, compareVersionsParsed(parsed, target))) {
      return false;
    }
  }
  if (parsed.hasPrerelease) {
    const anchored = comparators.some(
      ({parsed: target}) =>
        target.hasPrerelease &&
        target.major === parsed.major &&
        target.minor === parsed.minor &&
        target.patch === parsed.patch
    );
    if (!anchored) return false;
  }
  return true;
}

export function satisfies(version, range) {
  const parsed = parseVersion(version);
  for (const comparators of parseRange(range)) {
    if (clauseSatisfies(parsed, comparators)) return true;
  }
  return false;
}

function fail(message) {
  process.stderr.write(`semver-range: ${message}\n`);
  process.exit(2);
}

function runCli() {
  try {
    const args = process.argv.slice(2);
    if (args.length !== 1) {
      throw new Error('expected exactly one argument: INPUT_JSON_FILE');
    }
    let document;
    try {
      document = JSON.parse(readFileSync(args[0], 'utf8'));
    } catch (error) {
      throw new Error(`cannot read input JSON file: ${error.message}`);
    }
    if (typeof document !== 'object' || document === null || Array.isArray(document)) {
      throw new Error('input JSON must be a non-null, non-array object');
    }
    if (!Array.isArray(document.versions)) {
      throw new Error('input JSON "versions" must be a dense array of version strings');
    }
    if (Object.keys(document.versions).length !== document.versions.length) {
      throw new Error('input JSON "versions" must be a dense array');
    }
    if (typeof document.range !== 'string') {
      throw new Error('input JSON "range" must be a range string');
    }
    const entries = document.versions.map((version, index) => {
      if (typeof version !== 'string') {
        throw new Error(`versions[${index}] must be a string`);
      }
      return {raw: version, parsed: parseVersion(version)};
    });
    const clauses = parseRange(document.range);
    const ordered = entries
      .map((entry, index) => ({entry, index}))
      .sort((a, b) => compareVersionsParsed(a.entry.parsed, b.entry.parsed) || a.index - b.index);
    const sorted = ordered.map(({entry}) => entry.raw);
    const satisfying = ordered
      .filter(({entry}) => clauses.some((comparators) => clauseSatisfies(entry.parsed, comparators)))
      .map(({entry}) => entry.raw);
    process.stdout.write(`${JSON.stringify({sorted, satisfying})}\n`);
  } catch (error) {
    fail(String((error && error.message) || error));
  }
}

// Run the CLI only when this file is the main module, never on import.
function isMainModule() {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return pathToFileURL(realpathSync(entry)).href === import.meta.url;
  } catch {
    return false;
  }
}

if (isMainModule()) runCli();

