import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {mkdtempSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {compareVersions, satisfies} from '../semver-range.js';

const SCRIPT = fileURLToPath(new URL('../semver-range.js', import.meta.url));

function runCli(args) {
  return spawnSync(process.execPath, [SCRIPT, ...args], {encoding: 'utf8'});
}

function withTempDir(t, fn) {
  const dir = mkdtempSync(join(tmpdir(), 'semver-range-test-'));
  t.after(() => rmSync(dir, {recursive: true, force: true}));
  fn(dir);
}

test('major/minor/patch compare numerically, build metadata is ignored', () => {
  assert.equal(compareVersions('0.9.0', '1.0.0'), -1);
  assert.equal(compareVersions('1.0.1', '1.1.0'), -1);
  assert.equal(compareVersions('2.0.0', '1.9.9'), 1);
  assert.equal(compareVersions('1.0.0', '1.0.0'), 0);
  assert.equal(compareVersions('1.0.0+a', '1.0.0+b'), 0);
  assert.equal(compareVersions('1.0.0+b.2', '1.0.0+a.1'), 0);
  // Numeric, not lexical: 10 is above 9 in every core part.
  assert.equal(compareVersions('9.0.0', '10.0.0'), -1);
  assert.equal(compareVersions('1.9.0', '1.10.0'), -1);
  assert.equal(compareVersions('1.0.9', '1.0.10'), -1);
});

test('prerelease ranks below its release and compares identifier by identifier', () => {
  assert.equal(compareVersions('1.0.0-rc', '1.0.0'), -1);
  assert.equal(compareVersions('1.0.0', '1.0.0-rc'), 1);
  assert.equal(compareVersions('1.0.0-rc', '1.0.1'), -1);
  assert.equal(compareVersions('1.0.0-alpha', '1.0.0-beta'), -1);
  assert.equal(compareVersions('1.0.0-Alpha', '1.0.0-alpha'), -1);
  assert.equal(compareVersions('1.0.0-1', '1.0.0-2'), -1);
  assert.equal(compareVersions('1.0.0-9', '1.0.0-10'), -1);
  assert.equal(compareVersions('1.0.0-1.2', '1.0.0-1.10'), -1);
  assert.equal(compareVersions('1.0.0-1', '1.0.0-alpha'), -1);
  assert.equal(compareVersions('1.0.0-alpha', '1.0.0-1'), 1);
  assert.equal(compareVersions('1.0.0-a', '1.0.0-a.1'), -1);
  assert.equal(compareVersions('1.0.0-a.1', '1.0.0-a'), 1);
  assert.equal(compareVersions('1.0.0-a.b-c', '1.0.0-a.b-c'), 0);
});

test('version validation throws on anything outside the grammar', () => {
  const valid = (v) => assert.doesNotThrow(() => compareVersions(v, v));
  const invalid = (v) => assert.throws(() => compareVersions(v, '1.0.0'), Error);

  valid('0.0.0');
  valid('1.2.3');
  valid('1.2.3-0');
  valid('1.2.3-0.1');
  valid('1.2.3-rc.1');
  valid('1.2.3-alpha-1');
  valid('1.2.3+build');
  valid('1.2.3+01');
  valid('1.2.3+0');
  valid('1.2.3+b.01-x');
  valid('1.2.3-rc+b');
  invalid('');
  invalid('1');
  invalid('1.2');
  invalid('1.2.3.4');
  invalid('01.2.3');
  invalid('1.02.3');
  invalid('1.2.03');
  invalid('-1.2.3');
