+  withTempDir(t, (dir) => {
+    const expectFailure = (args) => {
+      const result = runCli(args);
+      assert.equal(result.status, 2);
+      assert.equal(result.stdout, '');
+      assert.ok(result.stderr.length > 0);
+    };
+
+    expectFailure([]);
+    const file = join(dir, 'input.json');
+    writeFileSync(file, JSON.stringify({versions: ['1.0.0'], range: '1.0.0'}));
+    expectFailure([file, file]);
+
+    expectFailure([join(dir, 'missing.json')]);
+    expectFailure([dir]);
+
+    const write = (name, content) => {
+      const path = join(dir, name);
+      writeFileSync(path, content);
+      return path;
+    };
+    expectFailure([write('bad-json.json', '{"versions": [')]);
+    expectFailure([write('array.json', '[1, 2, 3]')]);
+    expectFailure([write('null.json', 'null')]);
+    expectFailure([write('string.json', '"1.0.0"')]);
+    expectFailure([write('no-versions.json', JSON.stringify({range: '1.0.0'}))]);
+    expectFailure([write('versions-not-array.json', JSON.stringify({versions: '1.0.0', range: '1.0.0'}))]);
+    expectFailure([write('range-not-string.json', JSON.stringify({versions: [], range: 5}))]);
+    expectFailure([write('bad-version.json', JSON.stringify({versions: ['1.0'], range: '1.0.0'}))]);
+    expectFailure([write('non-string-version.json', JSON.stringify({versions: [1.0], range: '1.0.0'}))]);
+    expectFailure([write('bad-range.json', JSON.stringify({versions: [], range: ''}))]);
+  });
+});
